for ax, c in zip(axs, C.CLASSES):
    s = g[g["class"] == c].sample(min(3000, (g["class"] == c).sum()), random_state=0)
    ax.scatter(np.log(s.AREA), s.entropyRR, s=2, alpha=0.4, color=col[c])
